#include <leveldb/db.h>
#include <string>
int main(){ leveldb::DB* db=nullptr; leveldb::Options o; o.create_if_missing=true; auto s=leveldb::DB::Open(o,"/tmp/forge-leveldb-oracle",&db); if(!s.ok()) return 1; s=db->Put(leveldb::WriteOptions(),"k","v"); std::string v; if(s.ok()) s=db->Get(leveldb::ReadOptions(),"k",&v); delete db; return s.ok() && v=="v" ? 0 : 2; }
